import React, { useState, useEffect } from "react";
import { Mail, Lock, Eye, EyeOff, User, UserPlus, Phone, MapPin, Calendar, Stethoscope, FileText } from "lucide-react";

// Configuración de axios (incluida en el componente para simplificar)
const axiosConfig = {
  baseURL: 'http://localhost:8080/api',
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
};

// Simulación de axios para el ejemplo
const mockAxios = {
  post: async (url, data) => {
    console.log('Enviando a:', url, data);
    // Simular delay de red
    await new Promise(resolve => setTimeout(resolve, 1500));

    if (url.includes('/auth/login')) {
      if (data.correo === 'admin@centro.com' && data.contrasena === 'admin123') {
        return { 
          data: { 
            success: true, 
            token: 'fake-jwt-token',
            usuario: {
              id: 1,
              correo: data.correo,
              rol: { nombre: 'ADMIN' },
              apoderado: null,
              trabajador: null
            }
          } 
        };
      } else if (data.correo === 'trabajador@centro.com' && data.contrasena === 'trabajo123') {
        return { 
          data: { 
            success: true, 
            token: 'fake-jwt-token-2',
            usuario: {
              id: 2,
              correo: data.correo,
              rol: { nombre: 'TRABAJADOR' },
              trabajador: {
                nombre: 'Juan',
                apellido: 'Pérez',
                cargo: 'Terapeuta',
                especialidad: 'Fisioterapia'
              }
            }
          } 
        };
      } else {
        throw new Error('Credenciales inválidas');
      }
    } else if (url.includes('/auth/solicitar-registro')) {
      return { 
        data: { 
          success: true, 
          message: 'Solicitud enviada exitosamente. Un administrador revisará tu solicitud.' 
        } 
      };
    }

    throw new Error('Endpoint no encontrado');
  }
};

export default function AuthSystem() {
  const [currentView, setCurrentView] = useState('login'); // 'login' o 'register'
  const [loginData, setLoginData] = useState({
    correo: "",
    contrasena: "",
  });

  const [registerData, setRegisterData] = useState({
    // Datos del usuario
    correo: "",
    contrasena: "",
    confirmarContrasena: "",
    tipoUsuario: "APODERADO", // APODERADO o TRABAJADOR

    // Datos específicos según el tipo
    nombre: "",
    apellido: "",
    telefono: "",
    direccion: "",

    // Solo para trabajadores
    cargo: "",
    especialidad: "",
  });

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState(""); // 'success' o 'error'

  // Ocultar navbar y footer cuando se monta el componente
  useEffect(() => {
    // Ocultar elementos de navegación
    const navbar = document.querySelector('nav, .navbar, [class*="nav"]');
    const footer = document.querySelector('footer, .footer, [class*="footer"]');

    if (navbar) navbar.style.display = "none";
    if (footer) footer.style.display = "none";

  }, []);

  const handleLoginChange = (e) => {
    const { name, value } = e.target;
    setLoginData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleRegisterChange = (e) => {
    const { name, value } = e.target;
    setRegisterData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage("");

    try {
      const response = await mockAxios.post("/auth/login", {
        correo: loginData.correo,
        contrasena: loginData.contrasena,
      });

      setMessage("¡Inicio de sesión exitoso!");
      setMessageType("success");

      // Aquí guardarías el token y datos del usuario
      console.log('Usuario logueado:', response.data.usuario);

      // Redirigir según el rol
      setTimeout(() => {
        const rol = response.data.usuario.rol.nombre;
        if (rol === 'ADMIN') {
          console.log('Redirigir al panel de administración');
        } else if (rol === 'TRABAJADOR') {
          console.log('Redirigir al panel de trabajador');
        } else if (rol === 'APODERADO') {
          console.log('Redirigir al panel de apoderado');
        }
      }, 2000);

    } catch (error) {
      setMessage("Error al iniciar sesión. Verifica tus credenciales.");
      setMessageType("error");
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage("");

    // Validaciones
    if (registerData.contrasena !== registerData.confirmarContrasena) {
      setMessage("Las contraseñas no coinciden");
      setMessageType("error");
      setLoading(false);
      return;
    }

    if (registerData.contrasena.length < 6) {
      setMessage("La contraseña debe tener al menos 6 caracteres");
      setMessageType("error");
      setLoading(false);
      return;
    }

    try {
      // Preparar datos para enviar
      const solicitudData = {
        correo: registerData.correo,
        contrasena: registerData.contrasena,
        tipoUsuario: registerData.tipoUsuario,
        datosPersona: {
          nombre: registerData.nombre,
          apellido: registerData.apellido,
          telefono: registerData.telefono,
          direccion: registerData.direccion,
          ...(registerData.tipoUsuario === 'TRABAJADOR' && {
            cargo: registerData.cargo,
            especialidad: registerData.especialidad,
          })
        }
      };

      const response = await mockAxios.post("/auth/solicitar-registro", solicitudData);

      setMessage(response.data.message);
      setMessageType("success");

      // Limpiar formulario
      setRegisterData({
        correo: "",
        contrasena: "",
        confirmarContrasena: "",
        tipoUsuario: "APODERADO",
        nombre: "",
        apellido: "",
        telefono: "",
        direccion: "",
        cargo: "",
        especialidad: "",
      });

    } catch (error) {
      setMessage("Error al enviar la solicitud. Inténtalo de nuevo.");
      setMessageType("error");
    } finally {
      setLoading(false);
    }
  };

  const switchView = (view) => {
    setCurrentView(view);
    setMessage("");
    setMessageType("");
  };

  return (
    <>
      <link
        href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap/5.3.0/css/bootstrap.min.css"
        rel="stylesheet"
      />



      <div className="auth-page-container">
        <div className="auth-card">
          {/* Header */}
          <div className="auth-header">
            <div className="auth-icon">
              {currentView === 'login' ? <User size={40} /> : <UserPlus size={40} />}
            </div>
            <h1 className="auth-title">CENTRO DE TERAPIAS</h1>
            <p className="auth-subtitle">JUAN PABLO II</p>
            <p className="auth-description">
              {currentView === 'login' ? 'Iniciar Sesión' : 'Solicitud de Registro'}
            </p>
          </div>

          {/* Body */}
          <div className="auth-body">
            {/* Tabs */}
            <div className="auth-tabs">
              <button 
                className={`auth-tab ${currentView === 'login' ? 'active' : ''}`}
                onClick={() => switchView('login')}
              >
                Iniciar Sesión
              </button>
              <button 
                className={`auth-tab ${currentView === 'register' ? 'active' : ''}`}
                onClick={() => switchView('register')}
              >
                Registrarse
              </button>
            </div>

            {/* Demo credentials */}
            {currentView === 'login' && (
              <div className="demo-credentials">
                <strong>Credenciales de prueba:</strong><br/>
                Admin: admin@centro.com / admin123<br/>
                Trabajador: trabajador@centro.com / trabajo123
              </div>
            )}

            {currentView === 'login' ? (
              /* LOGIN FORM */
              <div>
                <div className="auth-form-group">
                  <label className="auth-label">Correo Electrónico</label>
                  <div className="auth-input-group">
                    <Mail className="auth-input-icon" size={20} />
                    <input
                      name="correo"
                      type="email"
                      required
                      value={loginData.correo}
                      onChange={handleLoginChange}
                      className="auth-input"
                      placeholder="tu@email.com"
                    />
                  </div>
                </div>

                <div className="auth-form-group">
                  <label className="auth-label">Contraseña</label>
                  <div className="auth-input-group">
                    <Lock className="auth-input-icon" size={20} />
                    <input
                      name="contrasena"
                      type={showPassword ? "text" : "password"}
                      required
                      value={loginData.contrasena}
                      onChange={handleLoginChange}
                      className="auth-input"
                      placeholder="••••••••"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="auth-password-toggle"
                    >
                      {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                    </button>
                  </div>
                </div>

                <button
                  type="submit"
                  disabled={loading}
                  className="auth-btn"
                >
                  {loading ? (
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <div className="auth-spinner"></div>
                      Iniciando sesión...
                    </div>
                  ) : (
                    "Iniciar Sesión"
                  )}
                </button>
              </div>
            ) : (
              /* REGISTER FORM */
              <div>
                {/* Tipo de Usuario */}
                <div className="auth-form-group">
                  <label className="auth-label">Tipo de Usuario</label>
                  <select
                    name="tipoUsuario"
                    value={registerData.tipoUsuario}
                    onChange={handleRegisterChange}
                    className="auth-select"
                  >
                    <option value="APODERADO">Apoderado/Familiar</option>
                    <option value="TRABAJADOR">Trabajador/Profesional</option>
                  </select>
                </div>

                {/* Datos de Acceso */}
                <div className="auth-form-group">
                  <label className="auth-label">Correo Electrónico</label>
                  <div className="auth-input-group">
                    <Mail className="auth-input-icon" size={20} />
                    <input
                      name="correo"
                      type="email"
                      required
                      value={registerData.correo}
                      onChange={handleRegisterChange}
                      className="auth-input"
                      placeholder="tu@email.com"
                    />
                  </div>
                </div>

                <div className="two-column">
                  <div className="auth-form-group">
                    <label className="auth-label">Contraseña</label>
                    <div className="auth-input-group">
                      <Lock className="auth-input-icon" size={20} />
                      <input
                        name="contrasena"
                        type={showPassword ? "text" : "password"}
                        required
                        value={registerData.contrasena}
                        onChange={handleRegisterChange}
                        className="auth-input"
                        placeholder="••••••••"
                      />
                      <button
                        type="button"
                        onClick={() => setShowPassword(!showPassword)}
                        className="auth-password-toggle"
                      >
                        {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                      </button>
                    </div>
                  </div>

                  <div className="auth-form-group">
                    <label className="auth-label">Confirmar Contraseña</label>
                    <div className="auth-input-group">
                      <Lock className="auth-input-icon" size={20} />
                      <input
                        name="confirmarContrasena"
                        type={showConfirmPassword ? "text" : "password"}
                        required
                        value={registerData.confirmarContrasena}
                        onChange={handleRegisterChange}
                        className="auth-input"
                        placeholder="••••••••"
                      />
                      <button
                        type="button"
                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                        className="auth-password-toggle"
                      >
                        {showConfirmPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                      </button>
                    </div>
                  </div>
                </div>

                {/* Datos Personales */}
                <div className="two-column">
                  <div className="auth-form-group">
                    <label className="auth-label">Nombre</label>
                    <div className="auth-input-group">
                      <User className="auth-input-icon" size={20} />
                      <input
                        name="nombre"
                        type="text"
                        required
                        value={registerData.nombre}
                        onChange={handleRegisterChange}
                        className="auth-input"
                        placeholder="Tu nombre"
                      />
                    </div>
                  </div>

                  <div className="auth-form-group">
                    <label className="auth-label">Apellido</label>
                    <div className="auth-input-group">
                      <User className="auth-input-icon" size={20} />
                      <input
                        name="apellido"
                        type="text"
                        required
                        value={registerData.apellido}
                        onChange={handleRegisterChange}
                        className="auth-input"
                        placeholder="Tu apellido"
                      />
                    </div>
                  </div>
                </div>

                <div className="auth-form-group">
                  <label className="auth-label">Teléfono</label>
                  <div className="auth-input-group">
                    <Phone className="auth-input-icon" size={20} />
                    <input
                      name="telefono"
                      type="tel"
                      value={registerData.telefono}
                      onChange={handleRegisterChange}
                      className="auth-input"
                      placeholder="Tu número de teléfono"
                    />
                  </div>
                </div>

                <div className="auth-form-group">
                  <label className="auth-label">Dirección</label>
                  <div className="auth-input-group">
                    <MapPin className="auth-input-icon" size={20} />
                    <input
                      name="direccion"
                      type="text"
                      value={registerData.direccion}
                      onChange={handleRegisterChange}
                      className="auth-input"
                      placeholder="Tu dirección"
                    />
                  </div>
                </div>

                {/* Campos específicos para Trabajadores */}
                {registerData.tipoUsuario === 'TRABAJADOR' && (
                  <div className="two-column">
                    <div className="auth-form-group">
                      <label className="auth-label">Cargo</label>
                      <div className="auth-input-group">
                        <FileText className="auth-input-icon" size={20} />
                        <input
                          name="cargo"
                          type="text"
                          required
                          value={registerData.cargo}
                          onChange={handleRegisterChange}
                          className="auth-input"
                          placeholder="Ej: Terapeuta, Psicólogo"
                        />
                      </div>
                    </div>

                    <div className="auth-form-group">
                      <label className="auth-label">Especialidad</label>
                      <div className="auth-input-group">
                        <Stethoscope className="auth-input-icon" size={20} />
                        <input
                          name="especialidad"
                          type="text"
                          value={registerData.especialidad}
                          onChange={handleRegisterChange}
                          className="auth-input"
                          placeholder="Tu especialidad"
                        />
                      </div>
                    </div>
                  </div>
                )}

                <button
                  type="submit"
                  disabled={loading}
                  className="auth-btn"
                >
                  {loading ? (
                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <div className="auth-spinner"></div>
                      Enviando solicitud...
                    </div>
                  ) : (
                    "Enviar Solicitud de Registro"
                  )}
                </button>

                <div style={{ fontSize: '0.85rem', color: '#666', textAlign: 'center', marginTop: '1rem' }}>
                  <em>Tu solicitud será revisada por un administrador antes de ser aprobada.</em>
                </div>
              </div>
            )}

            {/* Message */}
            {message && (
              <div className={`auth-alert ${messageType}`}>
                {message}
              </div>
            )}

            {/* Footer */}
            <div className="auth-footer">
              <a href="mailto:informes@centrojuanpabloii.com" className="auth-link">
                ¿Necesitas ayuda? informes@centrojuanpabloii.com
              </a>
              <div style={{ fontSize: '0.8rem', color: '#888', marginTop: '1rem' }}>
                Centro de Terapias Juan Pablo II © 2024
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
